create extension if not exists pgcrypto;
create type public.app_role as enum ('user','editor','admin');
create type public.publish_status as enum ('draft','published','archived');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, role public.app_role not null default 'user', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.site_settings (id uuid primary key default gen_random_uuid(), site_key text not null unique, full_name text not null default 'Sidhu', headline text not null default 'Building things, learning fast.', bio text not null default '', email text, location text, avatar_url text, resume_url text, github_url text, linkedin_url text, instagram_url text, available_for_work boolean not null default true, seo_title text, seo_description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.skills (id uuid primary key default gen_random_uuid(), name text not null unique, category text, proficiency smallint check (proficiency between 0 and 100), sort_order integer not null default 0, status public.publish_status not null default 'published', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.experiences (id uuid primary key default gen_random_uuid(), title text not null, company text not null, location text, description text, start_date date not null, end_date date, is_current boolean not null default false, sort_order integer not null default 0, status public.publish_status not null default 'published', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (end_date is null or end_date >= start_date));
create table public.projects (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, summary text not null, description text, image_url text, live_url text, source_url text, featured boolean not null default false, sort_order integer not null default 0, status public.publish_status not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.project_skills (project_id uuid not null references public.projects(id) on delete cascade, skill_id uuid not null references public.skills(id) on delete cascade, primary key (project_id, skill_id));
create table public.achievements (id uuid primary key default gen_random_uuid(), title text not null, issuer text, description text, achievement_date date, url text, sort_order integer not null default 0, status public.publish_status not null default 'published', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.contact_messages (id uuid primary key default gen_random_uuid(), name text not null, email text not null, subject text, message text not null, status text not null default 'new' check (status in ('new','read','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.audit_logs (id bigint generated always as identity primary key, actor_id uuid references auth.users(id) on delete set null, action text not null, entity_type text not null, entity_id text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index skills_status_order_idx on public.skills(status, sort_order); create index experiences_status_order_idx on public.experiences(status, sort_order); create index projects_status_order_idx on public.projects(status, sort_order); create index projects_featured_idx on public.projects(featured) where featured = true; create index achievements_status_order_idx on public.achievements(status, sort_order); create index contact_messages_status_created_idx on public.contact_messages(status, created_at desc); create index audit_logs_actor_created_idx on public.audit_logs(actor_id, created_at desc); create index audit_logs_entity_idx on public.audit_logs(entity_type, entity_id);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['profiles','site_settings','skills','experiences','projects','achievements','contact_messages'] loop execute format('create trigger %I_updated_at before update on public.%I for each row execute function public.set_updated_at()', t, t); end loop; end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, display_name) values (new.id, coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email, '@', 1))) on conflict (id) do nothing; return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_admin_or_editor() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.profiles where id = auth.uid() and role in ('admin','editor')); $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin'); $$;
alter table public.profiles enable row level security; alter table public.site_settings enable row level security; alter table public.skills enable row level security; alter table public.experiences enable row level security; alter table public.projects enable row level security; alter table public.project_skills enable row level security; alter table public.achievements enable row level security; alter table public.contact_messages enable row level security; alter table public.audit_logs enable row level security;
create policy profiles_self_read on public.profiles for select using (id = auth.uid() or public.is_admin()); create policy profiles_admin_update on public.profiles for update using (public.is_admin()) with check (public.is_admin());
create policy settings_public_read on public.site_settings for select using (true); create policy settings_admin_write on public.site_settings for all using (public.is_admin_or_editor()) with check (public.is_admin_or_editor());
create policy skills_public_read on public.skills for select using (status = 'published' or public.is_admin_or_editor()); create policy skills_editor_write on public.skills for all using (public.is_admin_or_editor()) with check (public.is_admin_or_editor());
create policy experiences_public_read on public.experiences for select using (status = 'published' or public.is_admin_or_editor()); create policy experiences_editor_write on public.experiences for all using (public.is_admin_or_editor()) with check (public.is_admin_or_editor());
create policy projects_public_read on public.projects for select using (status = 'published' or public.is_admin_or_editor()); create policy projects_editor_write on public.projects for all using (public.is_admin_or_editor()) with check (public.is_admin_or_editor());
create policy project_skills_public_read on public.project_skills for select using (exists (select 1 from public.projects p where p.id = project_id and (p.status = 'published' or public.is_admin_or_editor()))); create policy project_skills_editor_write on public.project_skills for all using (public.is_admin_or_editor()) with check (public.is_admin_or_editor());
create policy achievements_public_read on public.achievements for select using (status = 'published' or public.is_admin_or_editor()); create policy achievements_editor_write on public.achievements for all using (public.is_admin_or_editor()) with check (public.is_admin_or_editor());
create policy contact_public_insert on public.contact_messages for insert with check (true); create policy contact_admin_read on public.contact_messages for select using (public.is_admin_or_editor()); create policy contact_admin_update on public.contact_messages for update using (public.is_admin_or_editor()) with check (public.is_admin_or_editor()); create policy contact_admin_delete on public.contact_messages for delete using (public.is_admin());
create policy audit_admin_read on public.audit_logs for select using (public.is_admin()); create policy audit_authenticated_insert on public.audit_logs for insert with check (auth.uid() is not null and actor_id = auth.uid());
insert into public.site_settings (site_key, full_name, headline, bio, seo_title, seo_description) values ('default','Sidhu','Building things, learning fast.','Welcome to my personal portfolio.','Sidhu — Personal Portfolio','Personal portfolio, projects, experience and achievements.') on conflict (site_key) do nothing;
